import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AmbientAlertProps = Record<string, any>;

const AmbientAlert: React.FC<AmbientAlertProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  iconColor = "#FF0000",
  iconSize = 250,
  pulseSpeed = 1.0,
  durationInSeconds = 15,
}) => {
  // Load fonts (boilerplate usage, though icon relies on SVG)
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Logic: Ambient Sine Wave
  // Calculate a continuous sine wave based on time (t) and speed
  const t = frame / fps;
  const sineWave = Math.sin(t * pulseSpeed * Math.PI); // Oscillates between -1 and 1

  // Map sine wave to properties
  // Scale breathes slightly from 100% to 110%
  const scale = interpolate(sineWave, [-1, 1], [1, 1.1]);
  
  // Opacity for the glow effect
  const glowOpacity = interpolate(sineWave, [-1, 1], [0.2, 0.6]);
  
  // Create a dynamic RGBA string for the drop shadow glow
  // Note: Simple hex to rgb conversion could be added, but for simplicity we assume the glow matches the icon color concept
  // We will apply the glow via filter drop-shadow
  
  const containerStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
  };

  const iconStyle: React.CSSProperties = {
    width: iconSize,
    height: iconSize,
    transform: `scale(${scale})`,
    // Apply a glowing drop-shadow that pulses in intensity
    filter: `drop-shadow(0px 0px ${30 * scale}px ${iconColor}) opacity(${0.8 + (glowOpacity * 0.2)})`,
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke={iconColor}
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={iconStyle}
      >
        {/* Alert Triangle */}
        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
        {/* Exclamation Mark Line */}
        <line x1="12" y1="9" x2="12" y2="13" />
        {/* Exclamation Mark Dot */}
        <line x1="12" y1="17" x2="12.01" y2="17" />
      </svg>
    </AbsoluteFill>
  );
};

export default AmbientAlert;